import {spawnSync} from "node:child_process";
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFileSync} from "node:fs";
import test from "node:test";
import {createTalliApiClient,TalliApiError,verifyAccountsCompanyArchive} from "../../packages/talli-api-client/src/index.ts";
import {buildPersistedCompanyArchive} from "../../apps/web/app/lib/archive.ts";
import {copyCompanyYearArchive,restoreCompanyYearArchive,assertRestoreIntegrity} from "../../apps/web/app/lib/backup-restore.ts";

// Generated by the owning Python codec from synthetic historical Corporate
// root/correction fixtures. Actual Corporate owner evidence runs in the browser lane.
const original=JSON.parse(readFileSync(new URL("../fixtures/accounts-company-archive-codec-v1.json",import.meta.url),"utf8"));
const sha=raw=>createHash("sha256").update(raw).digest("hex");
const client=value=>createTalliApiClient({baseUrl:"https://fixture.test",fetch:async()=>Response.json(value)});
const source=value=>JSON.parse(value.canonicalJson);
const rehash=(value,body)=>{value.canonicalJson=JSON.stringify(body);value.sha256=sha(value.canonicalJson);return value;};

test("Accounts generated archive client preserves complete root/correction bytes with current bearer scope",async()=>{
  let request;
  const api=createTalliApiClient({baseUrl:"https://fixture.test",headers:{Authorization:"Bearer synthetic"},fetch:async(url,options)=>{
    request={url:new URL(url),options};return Response.json(original);
  }});
  assert.deepEqual(await api.annualAccountsGetCompanyYearArchive(original.companyId,2025),original);
  assert.equal(request.url.pathname,"/api/v1/annual-accounts/company-year-archive");
  assert.equal(request.url.searchParams.get("companyId"),original.companyId);
  assert.equal(request.url.searchParams.get("incomeYear"),"2025");
  assert.equal(new Headers(request.options.headers).get("Authorization"),"Bearer synthetic");
  assert.equal(request.options.cache,"no-store");
});

test("shared company export/copy/restore retains original identities, source and all opaque records",async()=>{
  await verifyAccountsCompanyArchive(original,original.companyId,2025);
  const archive=buildPersistedCompanyArchive({company:{id:original.companyId},incomeYear:2025,setups:[],shareholders:[],
    ledgerEntries:[],documents:[],filingPreviews:[],filingSubmissions:[],accountsCompanyArchive:original});
  const copied=JSON.parse(JSON.stringify(archive));
  const restored=restoreCompanyYearArchive(copied,{targetCompanyId:"isolated-copy-metadata"});
  assert.deepEqual(restored.restored.annualAccountsCompanyArchive,original);
  assert.notEqual(restored.restored.annualAccountsCompanyArchive,copied.annualAccountsCompanyArchive);
  assert.equal(restored.manifest.counts.annualAccountsDeliveryDrafts,2);
  assert.equal(restored.manifest.counts.annualAccountsDeliveryEvents,original.eventCount);
  assert.equal(restored.manifest.counts.annualAccountsDeliveryOriginals,original.originalCount);
  assert.equal(restored.manifest.annualAccountsArchiveSha256,original.sha256);
  assert.equal(assertRestoreIntegrity(restored).failures.some(code=>code.startsWith("annual_accounts_")),false);
  copied.annualAccountsCompanyArchive.canonicalJson="changed after copy";
  assert.equal(restored.restored.annualAccountsCompanyArchive.canonicalJson,original.canonicalJson);
  const body=source(original);
  assert.ok(body.events.some(row=>JSON.parse(row.canonicalJson).record.original?.purpose==="pdf"));
  assert.ok(body.events.some(row=>JSON.parse(row.canonicalJson).record.original?.purpose==="signature"));
});

for (const defect of ["scope","year","hash","source","codec","missing-draft","missing-event","duplicate-event","order",
  "foreign-binding","foreign-actor","parent","coverage","original-bytes","count","original-count","extra"]) {
  test(`Accounts archive client and shared restore refuse ${defect}`,async()=>{
    const value=structuredClone(original),body=source(value);
    if(defect==="scope")value.companyId="15000000-0000-4000-8000-000000000099";
    else if(defect==="year")value.incomeYear=2024;
    else if(defect==="hash")value.sha256="0".repeat(64);
    else if(defect==="source")body.sourceSha256="0".repeat(64);
    else if(defect==="codec")body.contractVersion="future";
    else if(defect==="missing-draft")body.drafts.pop();
    else if(defect==="missing-event")body.events.pop();
    else if(defect==="duplicate-event")body.events[1]=body.events[0];
    else if(defect==="order")body.events.reverse();
    else if(defect==="coverage")body.coverage.deliveryImmutableValid=false;
    else if(defect==="original-bytes")body.events[5].canonicalJson+=" ";
    else if(defect==="count")value.eventCount--;
    else if(defect==="original-count")value.originalCount--;
    else if(defect==="extra")value.privileged=true;
    else {
      const index=defect==="parent"?body.events.findIndex(row=>JSON.parse(row.canonicalJson).record.parent_binding):0;
      const event=body.events[index],root=JSON.parse(event.canonicalJson);
      if(defect==="foreign-binding")root.record.binding.company_id.value="15000000-0000-4000-8000-000000000099";
      else if(defect==="foreign-actor")root.record.binding.actor_id.kind="SYSTEM";
      else root.record.parent_binding.filing_id=root.record.binding.filing_id;
      event.canonicalJson=JSON.stringify(root);event.sha256=sha(event.canonicalJson);
      body.coverage.deliveryEventDigests[String(event.sequence)]=event.sha256;
    }
    if(!["scope","year","hash","count","original-count","extra"].includes(defect))rehash(value,body);
    await assert.rejects(client(value).annualAccountsGetCompanyYearArchive(original.companyId,2025),error=>error instanceof TalliApiError&&error.status===502);
    const restored=restoreCompanyYearArchive({company:{id:original.companyId},incomeYear:2025,annualAccountsCompanyArchive:value},{targetCompanyId:original.companyId});
    assert.ok(assertRestoreIntegrity(restored).failures.includes("annual_accounts_archive_mismatch"));
  });
}

test("legacy archives and a removed restored Accounts source never claim full integrity",()=>{
  const missing=restoreCompanyYearArchive({company:{id:original.companyId},incomeYear:2025},{targetCompanyId:original.companyId});
  assert.ok(assertRestoreIntegrity(missing).failures.includes("annual_accounts_archive_missing"));
  const restored=restoreCompanyYearArchive({company:{id:original.companyId},incomeYear:2025,annualAccountsCompanyArchive:original},{targetCompanyId:original.companyId});
  restored.restored.annualAccountsCompanyArchive=null;
  assert.ok(assertRestoreIntegrity(restored).failures.includes("annual_accounts_archive_missing"));
});

test("Accounts shared export adds only its owned source inside the frozen generation receipt",async()=>{
  const {legacyOperationProof}=await import("../../scripts/check-architecture.mjs");
  const evidence=JSON.parse(readFileSync(new URL("../../architecture/evidence/issues/193/accounts/company-archive-composition-v1.json",import.meta.url),"utf8"));
  const current=readFileSync(new URL("../../"+evidence.path,import.meta.url),"utf8");
  const scope={operation:evidence.operation,resource:"table:filing_submissions"};
  assert.deepEqual(legacyOperationProof(current,evidence.path,scope),evidence.candidate);
  let prior=current;
  for(const addition of evidence.exactAdditions){assert.equal(prior.split(addition).length,2);prior=prior.replace(addition,"");}
  assert.deepEqual(legacyOperationProof(prior,evidence.path,scope),evidence.prior);
});

test("shared copy binds the exact external export receipt before parsing or restoring Accounts",()=>{
  const value=buildPersistedCompanyArchive({company:{id:original.companyId},incomeYear:2025,setups:[],shareholders:[],ledgerEntries:[],
    documents:[],filingPreviews:[],filingSubmissions:[],accountsCompanyArchive:original});
  const raw=JSON.stringify(value,null,2),expectedArchiveSha256=sha(raw);
  assert.equal(copyCompanyYearArchive(raw,{targetCompanyId:original.companyId,expectedArchiveSha256}).sourceArchiveSha256,expectedArchiveSha256);
  assert.throws(()=>copyCompanyYearArchive(raw+" ",{targetCompanyId:original.companyId,expectedArchiveSha256}));
  assert.throws(()=>copyCompanyYearArchive(raw,{targetCompanyId:original.companyId,expectedArchiveSha256:"0".repeat(64)}));
  value.annualAccountsCompanyArchive=null;const missing=JSON.stringify(value);
  assert.throws(()=>copyCompanyYearArchive(missing,{targetCompanyId:original.companyId,expectedArchiveSha256:sha(missing)}));
});

test("an independent Python copy reconstructs every original through the owning decoder",()=>{
  const python=process.env.TALLI_BACKEND_PYTHON_BIN||process.env.TALLI_PYTHON_BIN||"apps/backend/.venv/bin/python";
  const body=source(original),actor=JSON.parse(body.drafts[0].canonicalJson).draft.prepared_by.subject.value;
  const args=["scripts/check_accounts_company_archive.py","--company-id",original.companyId,"--income-year","2025","--actor-id",actor];
  const result=spawnSync(python,[...args,"--expected-sha256",original.sha256],{input:JSON.stringify(original),encoding:"utf8",timeout:60_000,maxBuffer:2*1024*1024});
  assert.equal(result.status,0,result.stderr);const copied=JSON.parse(result.stdout);
  assert.equal(copied.archiveSha256,original.sha256);assert.equal(copied.sourceSha256,original.sourceSha256);
  assert.equal(copied.draftCount,2);assert.equal(copied.eventCount,original.eventCount);assert.equal(copied.originals.length,original.originalCount);
  assert.ok(copied.originals.some(row=>row.purpose==="signature"));
  const refused=spawnSync(python,[...args,"--expected-sha256","0".repeat(64)],{input:JSON.stringify(original),encoding:"utf8",timeout:60_000,maxBuffer:2*1024*1024});
  assert.notEqual(refused.status,0);assert.equal(refused.stdout,"");
});
